import fs from 'node:fs';
import path from 'node:path';
import { CONTENT, GENERATED } from './paths.mjs';

const REGISTRY = 'https://dosepehr.github.io/frontend-foundation/r';
const HEADER = '// Generated by scripts/generate - do not edit.';

const yaml = (s) => JSON.stringify(s);

// Files written in this run; anything else in the output folders is stale.
const written = new Set();

// Writes only when the contents differ, so the dev server sees real edits
// instead of every generated file changing on each run.
export function writeIfChanged(file, contents) {
    written.add(file);
    if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === contents)
        return;
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, contents);
}

// Writes the per-component JSON consumed by the docs kit.
export function writeData(entry) {
    const file = path.join(GENERATED, 'data', `${entry.slug}.json`);
    writeIfChanged(file, `${JSON.stringify(entry, null, 2)}\n`);
}

// Client module that binds a component's stories to the docs kit.
export function writeClientModule(entry, storyImports) {
    const imports = storyImports
        .map((p, i) => `import * as stories${i} from '${p}';`)
        .join('\n');
    const list = storyImports.map((_, i) => `stories${i}`).join(', ');
    const code = `'use client';

${HEADER}
import { createComponentDocs } from '@/features/component-docs/createComponentDocs';
import type { ComponentDocsData } from '@/features/component-docs/types';
${imports}
import data from '../data/${entry.slug}.json';

const docs = createComponentDocs(data as ComponentDocsData, [${list}]);

export const Playground = docs.Playground;
export const Example = docs.Example;
export const Props = docs.Props;
`;
    const file = path.join(GENERATED, 'components', `${entry.slug}.tsx`);
    writeIfChanged(file, code);
}

// The component's docs page. Story headings live in the MDX so they show up
// in the table of contents and in search.
export function writePage(entry, info) {
    const examples = entry.storyFiles
        .flatMap((f) => f.stories)
        .filter((s) => s.id !== entry.playgroundStory)
        .map((s) => `### ${s.title}\n\n<Example id="${s.id}" />`)
        .join('\n\n');
    const mdx = `---
title: ${yaml(entry.title)}
description: ${yaml(info.description)}
---

{/* Generated by scripts/generate - edit content/components/${entry.slug}.md instead. */}

import { Playground, Example, Props } from '@/generated/components/${entry.slug}';

${entry.playgroundStory ? '<Playground />\n' : ''}
## Installation

\`\`\`bash
npx shadcn@latest add ${REGISTRY}/${entry.slug}.json
\`\`\`

## Usage

\`\`\`tsx
${entry.importLine}
\`\`\`
${info.notes ? `\n${info.notes.trim()}\n` : ''}
${examples ? `## Examples\n\n${examples}\n` : ''}
## API reference

<Props />
`;
    const file = path.join(CONTENT, entry.category, `${entry.slug}.mdx`);
    writeIfChanged(file, mdx);
}

const byTitle = (a, b) => a.title.localeCompare(b.title);

// Sidebar order for a category folder: grouped under `---Group---`
// separators when groups are given, otherwise alphabetical.
export function writeCategoryMeta(categoryId, title, entries, groups) {
    const pages = groups
        ? groups.flatMap((group) => {
              const inGroup = entries
                  .filter((e) => e.group === group)
                  .sort(byTitle);
              return inGroup.length
                  ? [`---${group}---`, ...inGroup.map((e) => e.slug)]
                  : [];
          })
        : [...entries].sort(byTitle).map((e) => e.slug);
    const file = path.join(CONTENT, categoryId, 'meta.json');
    writeIfChanged(file, `${JSON.stringify({ title, pages }, null, 2)}\n`);
}

/** Deletes generated files from earlier runs that this run didn't write. */
export function pruneOutput(dirs) {
    for (const dir of dirs) {
        if (!fs.existsSync(dir)) continue;
        for (const rel of fs.readdirSync(dir, { recursive: true })) {
            const file = path.join(dir, rel);
            if (fs.statSync(file).isFile() && !written.has(file))
                fs.rmSync(file);
        }
    }
}
